<?php
declare(strict_types=1);require_once __DIR__.'/common.php';
if(($_SERVER['REQUEST_METHOD']??'')!=='GET')fb_out(false,'Only GET requests are allowed.',['code'=>'METHOD_NOT_ALLOWED'],405);$pdo=fb_pdo();fb_schema($pdo);$token=trim((string)($_GET['token']??''));if($token==='')fb_out(false,'A secure ticket code is required.',['code'=>'TOKEN_REQUIRED'],401);$ticket=fb_access($pdo,$token);if(!$ticket)fb_out(false,'This support link is invalid or has expired.',['code'=>'INVALID_TICKET_LINK'],404);
$auth=fb_authorized($pdo,$ticket);
if((int)($ticket['user_id']??0)>0 && $auth['reason']==='granted'){fb_notify_user($pdo,(int)$ticket['user_id'],'Support conversation opened','Your LOVEMI support conversation is open.',(int)$ticket['ticket_id']);try{$pdo->prepare("UPDATE notifications SET is_read=1,read_at=CURRENT_TIMESTAMP WHERE user_id=:u AND reference_type='support_ticket' AND reference_id=:r")->execute([':u'=>(int)$ticket['user_id'],':r'=>(int)$ticket['ticket_id']]);}catch(Throwable $e){}}
$payload=['ticket'=>['id'=>(int)$ticket['ticket_id'],'name'=>$ticket['name'],'email'=>$ticket['email'],'category'=>$ticket['category'],'subject'=>$ticket['subject'],'source'=>$ticket['source'],'source_label'=>strtolower((string)$ticket['source'])==='contact'?'Contact Center':'Help Center','status'=>$ticket['status'],'status_label'=>match($ticket['status']){'awaiting_admin'=>'Awaiting Support','awaiting_user'=>'Awaiting User','solved'=>'Solved','closed'=>'Closed','received'=>'Received',default=>'Open'},'created_at'=>$ticket['created_at'],'updated_at'=>$ticket['updated_at'],'close_at'=>$ticket['close_at'],'access_type'=>$ticket['access_type']],'messages'=>[]];
if(!$auth['ok']){fb_out(true,'Verification required.',array_merge($payload,['access_granted'=>false,'verification_required'=>$auth['reason'],'email_mask'=>preg_replace('/(^.).*(@.*$)/','$1***$2',(string)$ticket['email']),'two_factor_required'=>true]));}
$payload['access_granted']=true;$payload['verification_required']=null;$payload['messages']=fb_messages($pdo,(int)$ticket['ticket_id']);fb_out(true,'Support conversation loaded.',$payload);
